create or replace function public.invite_enterprise_partner(p_network_id uuid,p_partner_business_id uuid) returns public.enterprise_partner_network_members language plpgsql security definer set search_path=public as $$ declare n public.enterprise_partner_networks; m public.enterprise_partner_network_members; begin select * into n from public.enterprise_partner_networks where id=p_network_id and owner_business_id in(select business_id from public.business_members where user_id=auth.uid()); if not found then raise exception 'network unavailable'; end if; if not exists(select 1 from public.businesses where id=p_partner_business_id) then raise exception 'partner business unavailable'; end if; insert into public.enterprise_partner_network_members(network_id,partner_business_id,status) values(n.id,p_partner_business_id,'invited') on conflict(network_id,partner_business_id) do update set status='invited' returning * into m; return m; end $$;
revoke all on function public.invite_enterprise_partner(uuid,uuid) from public,anon; grant execute on function public.invite_enterprise_partner(uuid,uuid) to authenticated;
create or replace function public.set_enterprise_partner_status(p_membership_id uuid,p_status text) returns public.enterprise_partner_network_members language plpgsql security definer set search_path=public as $$ declare m public.enterprise_partner_network_members; begin if p_status not in('active','paused','removed') then raise exception 'invalid partner status'; end if; update public.enterprise_partner_network_members x set status=p_status from public.enterprise_partner_networks n where x.id=p_membership_id and x.network_id=n.id and n.owner_business_id in(select business_id from public.business_members where user_id=auth.uid()) returning x.* into m; if not found then raise exception 'partner membership unavailable'; end if; return m; end $$;
revoke all on function public.set_enterprise_partner_status(uuid,text) from public,anon; grant execute on function public.set_enterprise_partner_status(uuid,text) to authenticated;
create or replace function public.record_enterprise_partner_metric(p_network_id uuid,p_metric_date date,p_visits bigint default 0,p_check_ins bigint default 0,p_reviews bigint default 0,p_preferred_uses bigint default 0,p_access_redemptions bigint default 0,p_promotion_redemptions bigint default 0) returns public.enterprise_partner_network_metrics language plpgsql security definer set search_path=public as $$ declare x public.enterprise_partner_network_metrics; begin if not exists(select 1 from public.enterprise_partner_networks where id=p_network_id and owner_business_id in(select business_id from public.business_members where user_id=auth.uid())) then raise exception 'network unavailable'; end if; insert into public.enterprise_partner_network_metrics(network_id,metric_date,visits,check_ins,reviews,preferred_uses,access_redemptions,promotion_redemptions) values(p_network_id,p_metric_date,greatest(0,p_visits),greatest(0,p_check_ins),greatest(0,p_reviews),greatest(0,p_preferred_uses),greatest(0,p_access_redemptions),greatest(0,p_promotion_redemptions)) on conflict(network_id,metric_date) do update set visits=excluded.visits,check_ins=excluded.check_ins,reviews=excluded.reviews,preferred_uses=excluded.preferred_uses,access_redemptions=excluded.access_redemptions,promotion_redemptions=excluded.promotion_redemptions returning * into x; return x; end $$;
revoke all on function public.record_enterprise_partner_metric(uuid,date,bigint,bigint,bigint,bigint,bigint,bigint) from public,anon; grant execute on function public.record_enterprise_partner_metric(uuid,date,bigint,bigint,bigint,bigint,bigint,bigint) to authenticated;
